mapper.select:
SELECT proInfo.PRODUCT_CODE,
proInfo.BRAND,
proInfo.PRO_SIZE,
mlc.LOCATION_TYPE,
mlc.CHANNEL
FROM t_mdm_product_info proInfo
LEFT JOIN T_MDM_LOCATION_CHANNEL mlc ON mlc.IS_DELETE = 0
AND proInfo.BRAND = mlc.BRAND
WHERE proInfo.IS_DELETE = 0
AND proInfo.BRAND = #{brand}
AND proInfo.PRO_SIZE = #{proSize}
AND mlc.LOCATION_TYPE = #{locationType}
AND mlc.CHANNEL = #{channel}

SELECT PRODUCT_CODE,
BRAND,
PRO_SIZE,
LOCATION_TYPE,
CHANNEL,
SUM(PLAN_QTY) salePlanQty,
count(1) AS saleSkuCount
FROM

WHERE `YEAR` = #{year}
AND `MONTH` = #{month}
AND FACTORY_CODE = #{factoryCode}
AND MONTH_PLAN_VERSION = #{monthPlanVersion}
AND BRAND = #{brand}
AND PRO_SIZE = #{proSize}
AND LOCATION_TYPE = #{locationType}
AND CHANNEL = #{channel}
GROUP BY PRODUCT_CODE,
BRAND,
PRO_SIZE,
LOCATION_TYPE,
CHANNEL

SET @targetYear = #{year}; SET @targetMonth = #{month}; SET @factoryCode = #{factoryCode};
-- 使用 CTE 提前计算每个记录的不同日期范围的总和 WITH preprocessed_data AS (SELECT p.PRODUCT_CODE, p.PRODUCT_DESC, p.BRAND, p.PRO_SIZE, p.LOCATION_TYPE, p.CHANNEL, p.PATTERN, p.REASON, proInfo.TIRE_TYPE, -- 计算 1 - 25 日的总和 CASE WHEN p.YEAR = @targetYear AND p.MONTH = @targetMonth THEN IFNULL(p.DAY_1, 0) + IFNULL(p.DAY_2, 0) + IFNULL(p.DAY_3, 0) + IFNULL(p.DAY_4, 0) + IFNULL(p.DAY_5, 0) + IFNULL(p.DAY_6, 0) + IFNULL(p.DAY_7, 0) + IFNULL(p.DAY_8, 0) + IFNULL(p.DAY_9, 0) + IFNULL(p.DAY_10, 0) + IFNULL(p.DAY_11, 0) + IFNULL(p.DAY_12, 0) + IFNULL(p.DAY_13, 0) + IFNULL(p.DAY_14, 0) + IFNULL(p.DAY_15, 0) + IFNULL(p.DAY_16, 0) + IFNULL(p.DAY_17, 0) + IFNULL(p.DAY_18, 0) + IFNULL(p.DAY_19, 0) + IFNULL(p.DAY_20, 0) + IFNULL(p.DAY_21, 0) + IFNULL(p.DAY_22, 0) + IFNULL(p.DAY_23, 0) + IFNULL(p.DAY_24, 0) + IFNULL(p.DAY_25, 0) ELSE 0 END AS day_1_25_sum, -- 计算 26 - 31 日的总和 CASE WHEN ( (@targetMonth = 1 AND p.YEAR = @targetYear - 1 AND p.MONTH = 12) OR (p.YEAR = @targetYear AND p.MONTH = @targetMonth - 1) ) THEN IFNULL(p.DAY_26, 0) + IFNULL(p.DAY_27, 0) + IFNULL(p.DAY_28, 0) + IFNULL(p.DAY_29, 0) + IFNULL(p.DAY_30, 0) + IFNULL(p.DAY_31, 0) ELSE 0 END AS day_26_31_sum FROM T_MP_MONTH_PLAN_PROD_FINAL p LEFT JOIN t_mdm_product_info proInfo ON p.PRODUCT_CODE = proInfo.PRODUCT_CODE AND proInfo.FACTORY_CODE = @factoryCode WHERE ( (p.YEAR = @targetYear AND p.MONTH IN (@targetMonth, @targetMonth - 1)) OR (@targetMonth = 1 AND p.YEAR = @targetYear - 1 AND p.MONTH = 12) ) AND p.FACTORY_CODE = @factoryCode AND p.IS_DELETE = 0) -- 主查询分组汇总数据 SELECT ppd.PRODUCT_CODE, ppd.PRODUCT_DESC, ppd.BRAND, ppd.PRO_SIZE, ppd.LOCATION_TYPE, ppd.CHANNEL, ppd.PATTERN, ppd.TIRE_TYPE, ppd.REASON AS notSatisfiedReason, CASE WHEN IFNULL(ppd.day_1_25_sum, 0) + IFNULL(ppd.day_26_31_sum, 0) > 0 THEN 1 ELSE 0 END AS produceSkuCount, IFNULL(ppd.day_1_25_sum, 0) + IFNULL(ppd.day_26_31_sum, 0) AS producePlanQty
FROM preprocessed_data ppd

SET @targetYear = #{year}; SET @targetMonth = #{month}; SET @factoryCode = #{factoryCode}; SET @monthPlanVersion = #{monthPlanVersion};
SELECT p.PRODUCT_CODE, p.PRODUCT_DESC, p.BRAND, p.PRO_SIZE, p.LOCATION_TYPE, p.CHANNEL, p.PATTERN, proInfo.TIRE_TYPE, CASE WHEN IFNULL(p.PLAN_QTY, 0) > 0 THEN 1 ELSE 0 END AS saleSkuCount, IFNULL(p.PLAN_QTY, 0) AS salePlanQty FROM
p LEFT JOIN t_mdm_product_info proInfo ON p.PRODUCT_CODE = proInfo.PRODUCT_CODE AND proInfo.FACTORY_CODE = @factoryCode WHERE p.YEAR = @targetYear AND p.MONTH = @targetMonth AND p.FACTORY_CODE = @factoryCode AND p.MONTH_PLAN_VERSION = @monthPlanVersion AND p.IS_DELETE = 0

SET @targetYear = #{year}; SET @targetMonth = #{month}; SET @factoryCode = #{factoryCode};
SELECT p.PRODUCT_CODE, p.PRODUCT_DESC, p.LOCATION_TYPE, proInfo.BRAND, proInfo.PRO_SIZE, proInfo.PATTERN, proInfo.TIRE_TYPE, mlc.LOCATION_TYPE, CASE WHEN IFNULL(p.STOCK_QTY, 0) > 0 THEN 1 ELSE 0 END AS stockSkuCount, IFNULL(p.STOCK_QTY, 0) AS stockQty FROM
p LEFT JOIN t_mdm_product_info proInfo ON p.PRODUCT_CODE = proInfo.PRODUCT_CODE AND proInfo.FACTORY_CODE = @factoryCode LEFT JOIN T_MDM_LOCATION_CHANNEL mlc ON mlc.IS_DELETE = 0 AND proInfo.BRAND = mlc.BRAND WHERE p.IS_DELETE = 0 AND p.`YEAR` = @targetYear - 1 AND p.`MONTH` = 12 AND p.`YEAR` = @targetYear AND p.`MONTH` = @targetMonth - 1 AND p.FACTORY_CODE = @factoryCode

SELECT count(1) count,
SUM(PLAN_QTY) qty
FROM

WHERE IS_DELETE = 0
AND `YEAR` = #{queryDto.year}
AND `MONTH` = #{queryDto.month}
AND MONTH_PLAN_VERSION = #{queryDto.monthPlanVersion}

    AND ORDER_NO IN

        #{orderNo}

SELECT
proPlanInit.PRODUCT_CODE,
proPlanInit.FACT_PROD_REQ_QTY AS totalSalePlanQty,
CASE WHEN IFNULL(FACT_PROD_REQ_QTY, 0) > 0 THEN 1 ELSE 0 END AS saleSkuCount,
stock.STOCK_QTY
FROM T_MP_PROC_MONTH_PLAN_INIT proPlanInit
LEFT JOIN (
SELECT PRODUCT_CODE,
SUM(STOCK_QTY) STOCK_QTY FROM

WHERE IS_DELETE = 0
AND `YEAR` = #{year} - 1 AND `MONTH` = 12
AND `YEAR` = #{year} AND `MONTH` = #{month} - 1
AND FACTORY_CODE = #{factoryCode}
GROUP BY PRODUCT_CODE
) stock ON stock.PRODUCT_CODE = proPlanInit.PRODUCT_CODE

WHERE proPlanInit.IS_DELETE = 0
AND proPlanInit.`YEAR` = #{year}
AND proPlanInit.`MONTH` = #{month}
AND proPlanInit.FACTORY_CODE = #{factoryCode}
AND proPlanInit.MONTH_PLAN_VERSION = #{monthPlanVersion}
AND proPlanInit.CONSTRUCTION_STAGE IN(0, 1, 2)
AND proPlanInit.CHANNEL = #{channel}

SELECT
*
FROM

p
WHERE
p.YEAR = #{year}
AND p.MONTH = #{month}
AND p.FACTORY_CODE = #{factoryCode}
AND p.MONTH_PLAN_VERSION = #{monthPlanVersion}
AND p.IS_DELETE = 0

SELECT *
FROM

WHERE IS_DELETE = 0
AND `YEAR` = #{year}
AND `MONTH` = #{month}
AND FACTORY_CODE = #{factoryCode}

SELECT DISTINCT YEAR, MONTH, FACTORY_CODE, MONTH_PLAN_VERSION
FROM t_mp_moulding_day_result
WHERE IS_DELETE = 0 AND PRODUCTION_VERSION = #{monthPlanVersion}

SELECT * FROM t_mp_month_plan_adjust_notice WHERE IS_DELETE = 0 AND `STATUS` = 1 AND `YEAR` = #{year} AND `MONTH` = #{month}
AND BRAND IS NOT NULL
AND PRO_SIZE IS NOT NULL

SELECT MAX(PRODUCTION_VERSION)
FROM t_mp_month_plan_prod_final
WHERE `YEAR` = #{year}
  AND `MONTH` = #{month}
